{"file_path":"src/parser.js","content":"/**
 * Parses an election description from raw input text into a structured
 * form: the ordered list of declared candidate names and the list of
 * ballots (each a count and an ordered list of candidate names).
 *
 * Throws a ParseError carrying the exact message (and, when applicable,
 * the 1-based line number) required by the CLI's error reporting.
 */

const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9][0-9]*$/

export class ParseError extends Error {
  constructor(message) {
    super(message)
  }
}

function fail(message) {
  throw new ParseError(message)
}

export function parseElection(input) {
  const rawLines = input.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') {
    rawLines.pop()
  }

  let candidateNames = null
  const candidateSet = new Set()
  let sawBallot = false
  const ballots = []

  for (let i = 0; i < rawLines.length; i++) {
    const lineNo = i + 1
    const trimmed = rawLines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const word = tokens[0]

    if (word === 'candidates') {
      if (candidateNames !== null || sawBallot) {
        fail(`line ${lineNo}: candidates must be declared once, before any ballot`)
      }
      if (tokens.length < 2) {
        fail(`line ${lineNo}: expected candidates <name>...`)
      }
      const names = []
      const seen = new Set()
      for (const name of tokens.slice(1)) {
        if (!NAME_RE.test(name)) {
          fail(`line ${lineNo}: invalid candidate name ${name}`)
        }
        if (seen.has(name)) {
          fail(`line ${lineNo}: candidate ${name} is declared twice`)
        }
        seen.add(name)
        names.push(name)
      }
      candidateNames = names
      for (const name of names) candidateSet.add(name)
    } else if (word === 'ballot') {
      if (candidateNames === null) {
        fail(`line ${lineNo}: candidates must be declared once, before any ballot`)
      }
      sawBallot = true
      if (tokens.length < 3) {
        fail(`line ${lineNo}: expected ballot <count> <candidate>...`)
      }
      const countStr = tokens[1]
      if (!COUNT_RE.test(countStr)) {
        fail(`line ${lineNo}: count must be a positive integer`)
      }
      const count = Number(countStr)
      const names = tokens.slice(2)
      const seen = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) {
          fail(`line ${lineNo}: unknown candidate ${name}`)
        }
        if (seen.has(name)) {
          fail(`line ${lineNo}: candidate ${name} is repeated`)
        }
        seen.add(name)
      }
      ballots.push({ count, names })
    } else {
      fail(`line ${lineNo}: unknown directive ${word}`)
    }
  }

  if (candidateNames === null) {
    fail('no candidates')
  }

  return { candidates: candidateNames, ballots }
}
"}

