{"file_path":"src/election.js","content":"/**
 * Runs an instant-runoff count over a parsed election (candidates and
 * ballots) and returns the sequence of rounds plus the eventual winner.
 */

function tieBreakEliminate(tied, history) {
  let candSet = tied.slice()
  for (let r = 0; r < history.length && candSet.length > 1; r++) {
    const counts = candSet.map((c) => history[r].get(c))
    const first = counts[0]
    const allEqual = counts.every((v) => v === first)
    if (!allEqual) {
      const minV = Math.min(...counts)
      candSet = candSet.filter((c) => history[r].get(c) === minV)
    }
  }
  if (candSet.length === 1) return candSet[0]
  return candSet.reduce((a, b) => (a > b ? a : b))
}

export function countElection(candidates, ballots) {
  let continuing = new Set(candidates)
  const history = []
  const rounds = []
  let winner = null

  while (true) {
    const votes = new Map()
    for (const c of continuing) votes.set(c, 0)
    let exhausted = 0

    for (const ballot of ballots) {
      const target = ballot.names.find((n) => continuing.has(n))
      if (target === undefined) {
        exhausted += ballot.count
      } else {
        votes.set(target, votes.get(target) + ballot.count)
      }
    }

    let activeTotal = 0
    for (const v of votes.values()) activeTotal += v

    history.push(votes)

    let roundWinner = null
    if (activeTotal > 0) {
      for (const [c, v] of votes) {
        if (v * 2 > activeTotal) {
          roundWinner = c
          break
        }
      }
    }

    let eliminated = null
    if (activeTotal === 0) {
      winner = null
    } else if (roundWinner !== null) {
      winner = roundWinner
    } else {
      let minVal = Infinity
      for (const v of votes.values()) if (v < minVal) minVal = v
      const tied = [...continuing].filter((c) => votes.get(c) === minVal)
      eliminated = tied.length === 1 ? tied[0] : tieBreakEliminate(tied, history)
    }

    rounds.push({ votes, exhausted, eliminated, winner: activeTotal === 0 || roundWinner !== null ? winner : null })

    if (activeTotal === 0 || roundWinner !== null) {
      break
    }

    continuing = new Set([...continuing].filter((c) => c !== eliminated))
  }

  return { rounds, winner }
}
"}

